SELECT id, recipient_id, recipient_type, type, category, title, content, status, is_read AS `read`,
       related_type, related_id, sent_at, sent_at AS created_at
FROM c_notification
WHERE recipient_id = #{recipientId} AND recipient_type = #{recipientType}
ORDER BY sent_at DESC, id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM c_notification
WHERE recipient_id = #{recipientId} AND recipient_type = #{recipientType}

